                ; Initializes a display mode based on the input parameter (A)
                ;
                ; Input
                ;   A = The display mode to initialize
                ;       - 0: Plain text display (40 characters x 25 rows @ $0400 [DISP_START], 1bpp character set)
                ;            Sets CurDList_L/H = $199d [DLIST_40x24]
                ;            Sets 1 byte @ $04c8 [DISP_LINE6] to 0
                ;            Jumps to sdmInitPlainTxt
                ;
                ;       - 1: Normal gameplay display
                ;            23 total lines of text
                ;                6 lines of text     (40 characters, 1bpp character set)
                ;                9 lines of gfx area (40 characters, 2bpp character set used as graphics)
                ;                8 lines of text     (40 characters, 1bpp character set)
                ;            Sets CurDList_L/H = $19be [DLIST_40x6_9_8]
                ;            Sets 40 bytes @ $04c8 [DISP_LINE6] to 0
                ;            Jumps to sdmInitGamePlay
                ;
                ;       - 2: Unused mode? Same as normal gameplay except only clears 20 bytes on DISP_LINE6
                ;            23 total lines of text
                ;                6 lines of text     (40 characters, 1bpp character set)
                ;                9 lines of gfx area (40 characters, 2bpp character set used as graphics)
                ;                8 lines of text     (40 characters, 1bpp character set)
                ;            Sets CurDList_L/H = $19be [DLIST_40x6_9_8]
                ;            Sets 20 bytes @ $04c8 [DISP_LINE6] to 0
                ;            Jumps to sdmInitScenario
                ;
                ; Output
                ;   dat_0253  - Set to 0 for mode 0 and 3 for modes 1 & 2
                ;
1a0d: aa        setDisplayMode  TAX                  ; Set X = A
1a0e: 8d b9 18                  STA CUR_DLIST_NUM    ; Set CUR_DLIST_NUM = A
1a11: a9 00                     LDA #$00             ; Set A = 0
1a13: a0 03                     LDY #$03             ; Set Y = 3                      (4 iterations: 3..0)
1a15: 8c 53 02                  STY dat_0253         ; Set dat_0253 = 3
1a18: 99 00 d0  loc_1a18        STA HPOSP0,Y         ; Loop                           (Zero out each
                                                     ;     Set HPOSP0[Y] = 0           of the HPOSP0/1/2/3
1a1b: 88                        DEY                  ;     Subtract 1 from Y           registers)
1a1c: 10 fa                     BPL loc_1a18         ; Repeat while (Y >= 0)
1a1e: 20 54 24                  JSR waitForVblankA   ; Call $2454 [waitForVblankA]    (Wait for next VBLANK)
1a21: bd ef 19                  LDA DList4Mode_H,X   ; Set
1a24: 8d 55 02                  STA CurDList_H       ;     CurDList_L/H               (one of: $199d [DLIST_40x24],
1a27: bd f2 19                  LDA DList4Mode_L,X   ;     to                                  $19be [DLIST_40x6_9_8],
1a2a: 8d 54 02                  STA CurDList_L       ;     DList4Mode_L/H[X]                   $19be [DLIST_40x6_9_8])
1a2d: bc 21 1c                  LDY tbl_CLEAR_NUM,X  ; Set Y = tbl_CLEAR_NUM[X]       (one of: $00, $27 (39), $13 (19))
1a30: a9 00                     LDA #$00             ; Set A = 0
1a32: 99 c8 04  loc_1a32        STA DISP_LINE6,Y     ; Loop                           (Set Y+1 bytes
                                                     ;     Set DISP_LINE6[Y]           to 0
1a35: 88                        DEY                  ;     Subtract 1 from Y           starting
1a36: 10 fa                     BPL loc_1a32         ; Repeat while (Y >= 0)           @ $04c8 [DISP_LINE6])
1a38: bd 41 1a                  LDA DispInitSub_H,X  ; Load the address
1a3b: 48                        PHA                  ;     to continue at
1a3c: bd 44 1a                  LDA DispInitSub_L,X  ;     onto the stack
1a3f: 48                        PHA                  ;     from DispInitSub_H/L[X]
1a40: 60                        RTS                  ; Indirectly jump to continuation address loaded above
                                                     ;     0 = $1a46 + 1 = $1a47 (sdmInitPlainTxt)
                                                     ;     1 = $1a64 + 1 = $1a65 (sdmInitGamePlay)
                                                     ;     2 = $1b18 + 1 = $1b19 (sdmInitScenario)

1a41: 1a 1a 1b  DispInitSub_H   .BYTE $1a,$1a,$1b    ; Table of MSB for continuation address - 1
1a44: 46 64 18  DispInitSub_L   .BYTE $46,$64,$18    ; Table of LSB for continuation address - 1

                ; Invoked from setDisplayMode to initialize mode 0 (40x24 plain text)
                ;   - Sets VDSLST and CUR_VDSLSTL/H to $551b [irq_VDSLST_1b55]
                ;   - Sets all of HPOSP0/1/2/3 and HPOSM0/1/2/3 to 0
                ;   - Sets dat_0253 = 0
                ;
1a47: a9 55     sdmInitPlainTxt  LDA #$55            ; Set VDSLST
1a49: 8d 00 02                  STA VDSLST           ;     (display list interrupt vector)
1a4c: 8d 48 02                  STA CUR_VDSLSTL      ;     and CUR_VDSLSTL/H
1a4f: a9 1b                     LDA #$1b             ;     to
1a51: 8d 01 02                  STA VDSLST+1         ;     $551b
1a54: 8d 49 02                  STA CUR_VDSLSTH      ;     [irq_VDSLST_1b55]
1a57: a2 07                     LDX #$07             ; Set X = 7 (8 iterations: 7..0)
1a59: a9 00                     LDA #$00             ; Set A = 0
1a5b: 9d 00 d0  loc_1a5b        STA HPOSP0,X         ; Loop                         (Zero out all of
                                                     ;     Set HPOSP0[X] = 0         the HPOSP0/1/2/3
1a5e: ca                        DEX                  ;     Subtract 1 from X         and HPOSM0/1/2/3
1a5f: 10 fa                     BPL loc_1a5b         ; Repeat while (X >= 0)         registers)
1a61: 8d 53 02                  STA dat_0253         ; Set dat_0253 = 0
1a64: 60                        RTS                  ; Return to caller

                ; Invoked from setDisplayMode to initialize mode 1 (Normal game play)
                ;
                ;   - Sets VDSLST (display list interrupt vector) to $1b2f [irq_VDSLST_1b2f]
                ;   - Sets VDSLST_A_LO/HI to $1b56 [irq_VDSLST_1b56]
                ;   - Enables Display List Interrupts (DLI) and Vertical Blank Interrupts (VBI)
                ;   - Sets P0 and P1 size to quadruple size (32 pixels wide)
                ;   - Initializes player 0/1/2/3 bits to 0
                ;   - Initializes missile 0/1/2/3 color to 0
                ;   - Set all missile 0/1/2/3 bits to 1
                ;   - Set missile horizontal positions
                ;     - HPOSM0 = $20 (32)
                ;     - HPOSM1 = $28 (40)
                ;     - HPOSM2 = $d0 (208)
                ;     - HPOSM3 = $d8 (216)
                ;   - Set player horizontal positions
                ;     - HPOSP0 = $38 (56)
                ;     - HPOSP1 = $ac (172)
                ;     - HPOSP2 = $00 (0)
                ;     - HPOSP3 = $00 (0)
                ;   - Disables player and missile rendering
                ;   - Set all of CUR_COLPF0/1/2/3, CUR_COLBK and COLBK_SET_18Be to 0
                ;   - Initializes the graphical display area, calling initGfxArea
                ;   - Sets the sign bit on the 10 left-most (compass) and right-most (arrows) columns in the Gfx area
                ;   - Sets all 3072 bytes in GfxTopCharset, GfxMidCharset and GfxBtmCharset to $ff
                ;
                ; Output
                ;   VDSLST         - Assigned to irq_VDSLST_1b2f
                ;   CUR_VDSLSTL/H  - Assigned to irq_VDSLST_1b2f
                ;   VDSLST_A_LO/HI - Assigned to irq_VDSLST_1b56
                ; TODO: complete...
                ;
                ; Temp
                ;   SourceAdr_L/H - Used while updating display buffer chars
                ;   DestAdr_L/H   - Used while updating display buffer chars and graphics charsets
                ;
1a65: a9 2f     sdmInitGamePlay  LDA #$2f            ; Set VDSLST
1a67: 8d 00 02                  STA VDSLST           ;     (display list interrupt vector)
1a6a: 8d 48 02                  STA CUR_VDSLSTL      ;     and CUR_VDSLSTL/H
1a6d: a9 1b                     LDA #$1b             ;     to
1a6f: 8d 01 02                  STA VDSLST+1         ;     $1b2f
1a72: 8d 49 02                  STA CUR_VDSLSTH      ;     [irq_VDSLST_1b2f]
1a75: a9 56                     LDA #$56             ; Set
1a77: 8d 4a 02                  STA VDSLST_A_LO      ;     VDSLST_A_LO/HI
1a7a: a9 1b                     LDA #$1b             ;     to
1a7c: 8d 4b 02                  STA VDSLST_A_HI      ;     $1b56 [irq_VDSLST_1b56]
1a7f: a9 c0                     LDA #$c0             ; Set                 ($40 = Enable Display List Interrupt (DLI)
1a81: 8d 0e d4                  STA NMIEN            ;     NMIEN = $c0      $80 = Enable Vertical Blank Interrupt (VBI))
1a84: a9 00                     LDA #$00             ; Set
1a86: 8d b8 18                  STA CUR_COLPF2_NUM   ;     CUR_COLPF2_NUM = 0
1a89: a9 34                     LDA #$34             ; Set color priorities
