                ; The next three subs output interpolated strings to the display.
                ;
                ; The only difference between them is the "mode" employed.
                ; Each mode outputs to a different region of the screen and has a separately maintained output
                ; position and blinking text state preserved between calls.
                ;
                ; - printTop (mode 0) Outputs to top 6 rows of screen
                ; - printBtm (mode 1) Outputs to bottom 15 to 22 rows of screen
                ; - printAny (mode 2) Outputs anywhere on the screen (rows 0 .. 24)
                ;
                ;   dat_0023 = entry mode (0 via printTop, 1 via printBtm, 2 via printAny)
                ;
                ;   - Perform the following initialization:
                ;     OutCol         = SavedOutCol[X]
                ;     OutRow         = SavedOutRow[X] + ModeTopRow[X]
                ;     OutBlink       = SavedOutBlink[X]
                ;     OutAlign       = 0
                ;     OutAlignLen    = 0
                ;     OutAlignEolFlg = 0
                ;
                ;   - Reads characters from StrTmplate_L/H and calls alignOutputChr
                ;     until a byte is read with the sign bit set.
                ;   - Process byte with sign set
                ;      $a0         -> Turn off blinking text mode
                ;      $a1         -> Set blinking text mode
                ;      $a2         -> Start center-aligned text (clears from start of line)
                ;      $a3         -> Invoke subroutine at address in next 2 bytes
                ;      $a4         -> Reads address and outputs byte from that location as hex
