                ;               Set bit 4 (Enable VSEROR [$10 - data needed])
                ;   IRQEN     - Same value as CUR_IRQEN
                ;   AUDCTL    - $28  ($20 = Clock channel three with 1.79 MHz, $8 = Join channels 3 & 4 (16 bit))
                ;   AUDC1     - Set to $a0
                ;   AUDC2     - Set to $a0
                ;   AUDC3     - Set to $a0
                ;   AUDC4[X]  - Set to $a0
