2ba0: 0f 1f 3f 7f ff            .BYTE $0f,$1f,$3f,$7f,$ff  ; randInRange. Each entry has all bits numbered less
                                                           ; than or equal to the entry's index set to 1.

                ; Convert ATASCII character to upper case
                ;
                ; Input
                ;   A   - ATASCII code
                ;
                ; Output
