2dab: 8e db 2d  updateBit       STX smc_2dd9+2       ; Self-modifying code:
2dae: 8e e1 2d                  STX smc_2ddf+2       ;     Set MSB of base address to read & update
2db1: 8c da 2d                  STY smc_2dd9+1       ; Self-modifying code:
2db4: 8c e0 2d                  STY smc_2ddf+1       ;     Set LSB of base address to read & update
2db7: 48                        PHA                  ; Preserve current value of A
2db8: a9 1d                     LDA #$1d             ; Set A = $1d    (ORA abs,X)
2dba: a2 2e                     LDX #$2e             ; Set the source address
2dbc: a0 05                     LDY #$05             ;     operand for the ORA to $2e05 [InvBitNMask]
2dbe: b0 06                     BCS loc_2dc6         ; If C=1, skip next 3 instructions and apply "ORA InvBitNMask,X"
