2dc9: 8c dd 2d                  STY smc_2ddc+1       ; Set LSB of base address to read from (C=0 -> $2dfd [tbl_2dfd])
2dcc: 8e de 2d                  STX smc_2ddc+2       ; Set MSB of base address to read from (C=1 -> $2e05 [InvBitNMask])
2dcf: 68                        PLA                  ; Restore previous value of A
2dd0: 48                        PHA                  ; Preserve current value of A
2dd1: 29 07                     AND #$07             ; Set
2dd3: aa                        TAX                  ;     X = A & 7
2dd4: 68                        PLA                  ; Restore previous value of A
2dd5: 4a                        LSR                  ; Divide
2dd6: 4a                        LSR                  ;     A
2dd7: 4a                        LSR                  ;     by 8
