2de9: 48                        PHA                  ; Preserve current value of A
2dea: 29 07                     AND #$07             ; Set
2dec: aa                        TAX                  ;     X = A & 7
2ded: 68                        PLA                  ; Restore previous value of A
2dee: 4a                        LSR                  ; Divide
2def: 4a                        LSR                  ;     A
2df0: 4a                        LSR                  ;     by 8
2df1: a8                        TAY                  ; Set Y = A
