320d: ad 1f 63  loc_320d        LDA dat_631f         ; If
3210: c9 ff                     CMP #$ff             ;    (dat_631f != $ff)
3212: f0 0e                     BEQ loc_3222         ;
3214: ad 1e 63                  LDA dat_631e         ;    And
3217: cd 1f 63                  CMP dat_631f         ;    (dat_631e != dat_631f)
321a: d0 03                     BNE loc_321f         ;
