                ; Teleports the player to the teleport destination at MapCellSpclCode*4 of TlpDest
                ;
                ; Continues @ $318c [cont_318c] after updating the player position.
                ;
                ; Input
                ;   MapCellSpclCode - Teleport index (0..31)
                ;
                ; Output
