                ;                   0: CHR_PRI_WEAPON
                ;                   1: CHR_SEC_WEAPON
                ;                   2: CHR_ARMOR_HEAD
                ;                   3: CHR_ARMOR_BODY
                ;                   4: CHR_ARMOR_ARMS
                ;                   5: CHR_ARMOR_LEGS
